mapper.update:
update staff_organ_product
set organ_id = #{organId,jdbcType=BIGINT},
  organ_name = #{organName,jdbcType=VARCHAR},
  product_enum_id = #{productEnumId,jdbcType=BIGINT},
  product_enum_name = #{productEnumName,jdbcType=VARCHAR}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select p.*, o.acc_out_equal accOutEqual from staff_organ_product p left join staff_organ o on p.organ_id = o.id where o.delete_flag = 0 and o.state = 0
and o.id = #{staffOrgId,jdbcType=BIGINT}
and o.organ_attribute = #{organAttribute,jdbcType=INTEGER}
and find_in_set(o.id, #{orgIds,jdbcType=VARCHAR})
order by p.organ_id,p.product_enum_id

select

from staff_organ_product
where 1=1

 and  organ_id = #{organId,jdbcType=BIGINT}


  and product_enum_id = #{productEnumId,jdbcType=BIGINT}
